{
  "description": "The creature is a quadrupedal, cheetah-like mammal shown in right-facing profile standing on a small patch of sandy ground with sparse grass. Its head, neck, chest, belly, legs and tail are covered in tan fur with dense black spots like a cheetah, while its entire back from the shoulders to the rump is covered by a broad mantle of overlapping dark black feathers with a scaly-textured underlayer and a distinct white feathered border along the lower flank. It has a slender, muscular build, a short spotted tail with a dark tip, and a slightly ruffled spiky ruff along the back of the neck.",
  "parts": [
    {
      "part": "head",
      "looks_like": "cheetah-like head with tan fur, small black spots on the forehead and cheeks, prominent black tear-line running from the inner corner of the amber eye down to the mouth, white muzzle and chin with white whiskers, and a black nose",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, upright ears with tan fur outside and darker interior, slightly folded at the tips",
      "where": "on top of the head, one slightly behind the other in profile view"
    },
    {
      "part": "mane",
      "looks_like": "short, spiky, upright ruff of fur that is tan with black spots near the head transitioning to solid black feather-like tips",
      "where": "along the dorsal side of the neck from just behind the ears to the shoulders"
    },
    {
      "part": "legs",
      "looks_like": "four long, slender, muscular legs covered in tan fur with large solid black spots, front legs straight and vertical, hind legs bent at the hock joint",
      "where": "two under the chest at the front and two under the hips at the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large feline paws with rounded toes, visible dark claws, and tan spotted fur on top with lighter pads underneath",
      "where": "at the bottom ends of each leg resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "short to medium length, thick and bushy tail covered in tan fur with black spots and dark rings, ending in a bushy black tip with longer fur",
      "where": "extending from the rear of the body at the rump, hanging down behind the hind legs"
    },
    {
      "part": "feathers",
      "looks_like": "dense, overlapping, pointed black feathers with a glossy layered appearance, forming a continuous mantle",
      "where": "covering the entire dorsal surface from the base of the neck across the back to the base of the tail, with a clean edge above the flank"
    },
    {
      "part": "scales",
      "looks_like": "small, pebbly, dark grey-black scale-like texture visible beneath the larger feathers",
      "where": "on the lower side of the dark dorsal mantle, just above the white border along the mid-flank and hip"
    },
    {
      "part": "markings",
      "looks_like": "numerous solid round black spots of varying size over the tan fur, white fur on the throat, lower chest, belly and as a horizontal feathered stripe separating the dark back from the spotted sides, and a small yellow-tan patch on the shoulder at the front edge of the feather mantle",
      "where": "spots over head, neck, chest, sides, legs and tail; white on ventral areas and as a stripe along the flank; yellow patch on the shoulder"
    }
  ],
  "attached_objects": [],
  "animals": ["cheetah", "bird"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
